from v23.state_encoder import get as _v44_get
from v44.gold_floor import GoldFloorConfig as _V44Config
from v44.gold_floor import build_gold_floor_router as _v44_build

_V44_CONFIG = _V44Config(**{'yarn_third_start': 216, 'yarn_third_enabled': True, 'yarn_third_pet_brunch_veto': True, 'yarn_third_prefixes': (('SMOOTHIE_SHOP', 'SMOOTHIE_SHOP'),), 'bakery_capital_enabled': True, 'bakery_capital_start': 160, 'bakery_capital_second_shops': ('PIZZA_SHOP',), 'bakery_capital_minimum_cows': 3, 'bakery_capital_minimum_sheep': 2, 'bakery_capital_minimum_melons': 10, 'bakery_capital_maximum_geese': 0, 'controller': 'sparse', 'aligned_reorder': True, 'clone_preempt_horizon': 2, 'clone_streak_required': 24, 'clone_distance_threshold': 2.0, 'clone_detection_start': 48, 'clone_maximum_batch': 10, 'clone_active_start': 160, 'clone_requires_current_near': False, 'clone_veto_enabled': True, 'clone_veto_step': 120, 'clone_veto_first_shop': 'BAKERY', 'clone_veto_minimum_sheep': 4, 'clone_veto_maximum_cows': 1, 'clone_veto_minimum_wheat': 8, 'clone_veto_minimum_melons': 7, 'clone_veto_maximum_geese': 0, 'clone_phase_detector': True, 'clone_phase_horizon': 3, 'clone_phase_maximum_batch': 20, 'clone_phase_detection_start': 144, 'clone_phase_detection_stop': 159, 'clone_phase_minimum_excess_units': 2, 'clone_phase_maximum_excess_units': 4, 'clone_phase_future_window': 2, 'clone_phase_items': ('STRAWBERRY', 'MELON', 'MILK', 'WOOL'), 'exposure_preempt': False, 'wheat_market_maker': False, 'terminal_rule': 'collision'})
_V44_POLICY = _v44_build(_V44_ROUTES, _V44_CONFIG)


def agent(obs, configuration=None):
    try:
        return _V44_POLICY(obs, configuration)
    except Exception:
        seat = 1 if int(_v44_get(obs, "player", 0) or 0) == 1 else 0
        farms = list(_v44_get(obs, "farms", []) or [])
        farm = farms[seat] if seat < len(farms) else {}
        return {
            "farmer": ["PASS"],
            "hands": [["PASS"] for _ in (_v44_get(farm, "hands", []) or [])],
            "market": [],
        }


def _kaggle_submission_entrypoint(obs, configuration=None):
    return agent(obs, configuration)
